UPDATE ${tableName}
SET sell_order        = null,
    pre_ordered       = CASE WHEN state = 'PRE_ORDER' THEN false ELSE pre_ordered END,
    state             = CASE WHEN state = 'PRE_ORDER' THEN 'NOT_SIGN' ELSE state END,
    purchase_contract = CASE WHEN state = 'PRE_ORDER' THEN NULL ELSE purchase_contract END
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND sell_order = #{sellOrderCode}
